import{_ as a,o,c as n,a2 as t}from"./chunks/framework.CPzUcv0I.js";const h=JSON.parse('{"title":"Instances and Mod Catalog","description":"","frontmatter":{},"headers":[],"relativePath":"guide/players/instances-and-mods.md","filePath":"guide/players/instances-and-mods.md"}'),i={name:"guide/players/instances-and-mods.md"};function r(s,e,l,d,c,g){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="instances-and-mod-catalog" tabindex="-1">Instances and Mod Catalog <a class="header-anchor" href="#instances-and-mod-catalog" aria-label="Permalink to &quot;Instances and Mod Catalog&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Modloaders-Fabric%20%7C%20Forge%20%7C%20Quilt%20%7C%20NeoForge-blue.svg" alt="Modloaders"><img src="https://img.shields.io/badge/Catalogs-Modrinth%20%26%20CurseForge-green.svg" alt="Catalogs"></div><p>Gens Launcher offers fully isolated game profile management (&quot;Instances&quot;), drawing inspiration from leading tools like MultiMC and Prism Launcher, while integrating direct access to popular online mod catalogs.</p><hr><h2 id="creating-an-instance" tabindex="-1">Creating an Instance <a class="header-anchor" href="#creating-an-instance" aria-label="Permalink to &quot;Creating an Instance&quot;">​</a></h2><ol><li>In the top navigation bar, click <strong>New Instance</strong>.</li><li>Configure basic properties: <ul><li><strong>Instance Name:</strong> Provide a descriptive name (e.g., <em>Survival 1.21 Fabric</em>).</li><li><strong>Minecraft Version:</strong> Pick from all official releases, development snapshots, and historical builds.</li><li><strong>Modloader Engine:</strong> Choose your desired runtime: <ul><li><strong>Vanilla:</strong> Pure unmodified game files.</li><li><strong>Fabric:</strong> Modern, lightweight modloader, ideal for performance enhancements (Sodium, Lithium, Iris).</li><li><strong>Forge:</strong> The classic modloader for extensive tech and magic modpacks.</li><li><strong>Quilt:</strong> A modern fork compatible with the vast majority of Fabric mods.</li><li><strong>NeoForge:</strong> The modern evolution of Forge for Minecraft 1.20.2 and above.</li></ul></li></ul></li><li>Click <strong>Create</strong>. Gens Launcher retrieves official manifests and generates an isolated directory in <code>%AppData%\\GensLauncher\\instances\\&lt;Name&gt;</code>.</li></ol><hr><h2 id="configuring-java-and-memory-allocation-ram" tabindex="-1">Configuring Java and Memory Allocation (RAM) <a class="header-anchor" href="#configuring-java-and-memory-allocation-ram" aria-label="Permalink to &quot;Configuring Java and Memory Allocation (RAM)&quot;">​</a></h2><p>Every profile can specify its dedicated RAM allocation and Java runtime environment:</p><ol><li>Right-click your instance -&gt; <strong>Instance Settings</strong> (or select it and click the gear icon).</li><li><strong>RAM Allocation:</strong><ul><li><strong>Vanilla recommendation:</strong> 2 GB (<code>2048 MB</code>).</li><li><strong>Light modpacks:</strong> 4 GB (<code>4096 MB</code>).</li><li><strong>Heavy modpacks (200+ mods):</strong> 6 to 8 GB (<code>6144</code> to <code>8192 MB</code>).</li></ul></li><li><strong>Automatic Java Detection:</strong> Gens Launcher inspects your machine to find the appropriate Java version matching your target Minecraft edition: <ul><li><strong>Minecraft 1.16 and older:</strong> Java 8</li><li><strong>Minecraft 1.17:</strong> Java 16</li><li><strong>Minecraft 1.18 to 1.20.4:</strong> Java 17</li><li><strong>Minecraft 1.20.5 and newer:</strong> Java 21 or Java 25 If the required version is missing from your system, Gens Launcher offers automated one-click installation.</li></ul></li></ol><hr><h2 id="integrated-mod-and-content-browser" tabindex="-1">Integrated Mod and Content Browser <a class="header-anchor" href="#integrated-mod-and-content-browser" aria-label="Permalink to &quot;Integrated Mod and Content Browser&quot;">​</a></h2><p>No more browsing obscure websites to download unverified <code>.jar</code> files:</p><ol><li>Open your instance and switch to the <strong>Mods</strong> or <strong>Content</strong> tab.</li><li>Click <strong>Add Content</strong>.</li><li>Use the integrated search bar connected directly to <strong>Modrinth</strong> and <strong>CurseForge</strong> APIs.</li><li>Filter by category, game version, and modloader.</li><li>Click <strong>Install</strong>: <ul><li>The compatible <code>.jar</code> is downloaded straight into the instance&#39;s <code>mods/</code> directory.</li><li>Essential dependencies are identified automatically.</li></ul></li><li>Easily toggle mods on or off using simple switches without deleting their underlying files.</li></ol><hr><h2 id="shaders-and-resource-packs" tabindex="-1">Shaders and Resource Packs <a class="header-anchor" href="#shaders-and-resource-packs" aria-label="Permalink to &quot;Shaders and Resource Packs&quot;">​</a></h2><p>The catalog browser also supports additional cosmetic content:</p><ul><li><strong>Shader Packs:</strong> Search and apply shaders (Complementary, BSL, Iris Shaders) in one click.</li><li><strong>Resource Packs:</strong> Download high-resolution textures, custom audio packs, and fonts directly into <code>resourcepacks/</code>.</li></ul><hr><h2 id="importing-and-exporting-instances" tabindex="-1">Importing and Exporting Instances <a class="header-anchor" href="#importing-and-exporting-instances" aria-label="Permalink to &quot;Importing and Exporting Instances&quot;">​</a></h2><ul><li><strong>Export:</strong> Export any instance to a portable <code>.zip</code> archive ready to share with friends or store as an offline backup.</li><li><strong>Import:</strong> Click <strong>Import Instance</strong> to load standard archive formats (CurseForge modpacks, Modrinth modpacks, or MultiMC zip files).</li></ul>',21)])])}const u=a(i,[["render",r]]);export{h as __pageData,u as default};
